param([string]$Destination = (Join-Path (Get-Location) "ATM-Simulator-System")
$ErrorActionPreference = "Stop"
$payload = @"

"@
$bytes = [Convert]::FromBase64String(($payload -replace '\s',''))
$input = New-Object System.IO.MemoryStream(,$bytes)
$gzip = New-Object System.IO.Compression.GzipStream($input,[IO.Compression.CompressionMode]::Decompress)
$reader = New-Object IO.StreamReader($gzip,[Text.Encoding]::UTF8)
$manifest = $reader.ReadToEnd() | ConvertFrom-Json
New-Item -ItemType Directory -Force -Path $Destination | Out-Null
$manifest.PSObject.Properties | ForEach-Object {
  $path = Join-Path $Destination $_.Name
  New-Item -ItemType Directory -Force -Path (Split-Path $path) | Out-Null
  [IO.File]::WriteAllText($path,$_.Value,(New-Object Text.UTF8Encoding($false)))
}
$zip = "$Destination.zip"
if (Test-Path $zip) { Remove-Item $zip -Force }
Compress-Archive -Path $Destination -DestinationPath $zip -Force
Write-Host "Created project: $Destination"
Write-Host "Created archive: $zip"
